const todosItens = $input.all();
const inputParams = $items("Buscar Promoção4")[0].json;

const paginaAtual = 1;
const tipoSelecionado = inputParams.tipo;

// 3. Filtra os itens com base na categoria, disponibilidade e estoque
const itensFiltrados = todosItens
  .map(item => item.json)
  .filter(item => 
  parseInt(inputParams.property_estoque, 10) > 0)
;

// 4. Calcula quais itens mostrar nesta página específica
const itensDaPagina = itensFiltrados;

// 5. Prepara as variáveis para a resposta
let menuTexto = "";


// 8. Loop para construir o texto do menu e o mapa de IDs.
for (const item of itensDaPagina) {
  const preco = parseFloat(inputParams.property_pre_o).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const preco_promo = parseFloat(inputParams.property_pre_o_promo).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  // Monta a linha do menu de forma segura para a formatação do WhatsApp.
  let linhaDoMenu = `*🎁→* `;
  linhaDoMenu += ` *${item.property_nome.trim()}* `;
  linhaDoMenu += `\n\n_*Preço =*_ `;
  linhaDoMenu += `~${preco.trim()}~ `;
  linhaDoMenu += `*${preco_promo.trim()}*`;

  menuTexto += linhaDoMenu + `\n\n`;
}

// 9. Trata o caso de não haver itens para mostrar
if (itensDaPagina.length === 0) {
  menuTexto = (paginaAtual === 1) 
    ? `❌ DESCULPE, NÃO TEMOS NENHUMA PROMOÇÃO\nDISPONÍVEL NO MOMENTO.\n\u200B` 
    : "Não há mais itens para mostrar.\n";
}

// 6. Prepara o resultado para o Typebot
const resultado = {
  menu_formatado: menuTexto,
};

return [{ json: resultado }];

// 1. Pega os dados do Webhook (Nó WhatsApp Trigger).
// A estrutura correta para acessar os dados do nó anterior é:
// $items("Nome do Nó")[0].json.caminho.para.o.dado
// No caso do WhatsApp Trigger, o nome geralmente está em contacts[0].profile.name
const dadosTrigger = $items("WhatsApp Trigger");

let nomeOriginal = "";

// Verificação de segurança para garantir que o dado existe
if (dadosTrigger && dadosTrigger.length > 0 && 
    dadosTrigger[0].json.contacts && 
    dadosTrigger[0].json.contacts.length > 0 &&
    dadosTrigger[0].json.contacts[0].profile) {

    nomeOriginal = dadosTrigger[0].json.contacts[0].profile.name || "";
}

let nomeLimpo = "";

if (nomeOriginal) {
    // 2. A Mágica do Regex:
    // \p{Extended_Pictographic} -> Encontra qualquer caractere que seja um emoji ou símbolo gráfico.
    // /gu -> 'g' (global, remove todos) e 'u' (unicode, essencial para emojis).
    nomeLimpo = nomeOriginal.replace(/[\p{Extended_Pictographic}]/gu, '');

    // 3. Remove espaços extras que podem ter sobrado.
    // Ex: "João 🚀 Silva" vira "João  Silva" (com dois espaços). O trim() e replace arrumam isso.
    nomeLimpo = nomeLimpo.replace(/\s+/g, ' ').trim();
}

// 4. Retorna o nome limpo.
// Usamos return [{json: ...}] para manter o padrão do n8n
return [{
    json: {
        nome_sem_emoji: nomeLimpo
    }
}];
